package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;
public class DrySourceTests {
 static int passed;static void check(boolean c,String m){if(!c)throw new AssertionError(m);passed++;}
 static boolean same(Core.Clip a,Core.Clip b){if(a.length!=b.length)return false;for(int f=0;f<a.length;f++)for(int ch=0;ch<2;ch++)if(a.source.sample(a.offset+f,ch)!=b.source.sample(b.offset+f,ch))return false;return true;}
 static void remove(File f){File[] files=f.listFiles();if(files!=null)for(File c:files)remove(c);f.delete();}
 public static void main(String[] args)throws Exception {
  File dir=Files.createTempDirectory("city-dry-source").toFile();Core.Clip original=AudioIO.store(dir,StudioTests.wave(Core.RATE*2,446,.25),"Dry vocal",0);Core.Clip a=original.copy();a.offset=2400;a.length=72000;a.envelopeLength=72000;Core.Clip dryRegion=a.copy();PitchCorrector.Config hard=new PitchCorrector.Config();hard.retuneMs=0;AudioIO.correctClip(a,dir,hard);check(a.tuneSourceFile.equals(original.file)&&a.tuneSourceOffset==2400&&a.offset==0,"First tuning preserves the actual dry source and trim offset");check(new File(dir,original.file).isFile(),"Dry source remains available after processing");
  PitchCorrector.Config modern=new PitchCorrector.Config();modern.key=9;modern.scale=1;modern.retuneMs=20;Core.Clip fresh=dryRegion.copy();AudioIO.correctClip(fresh,dir,modern);AudioIO.correctClip(a,dir,modern);check(same(a,fresh),"Changing key and speed re-renders from dry, sample-identical to one fresh pass");Core.Clip previous=a.copy();AudioIO.correctClip(a,dir,modern);check(same(a,previous),"Repeated Apply is sample-identical rather than stacking artifacts");
  Core.Clip trimmed=a.copy();trimmed.offset=4800;trimmed.length-=9600;trimmed.envelopeOffset=4800;Core.Clip reference=dryRegion.copy();reference.offset+=4800;reference.length=trimmed.length;reference.envelopeOffset=4800;AudioIO.correctClip(trimmed,dir,modern);AudioIO.correctClip(reference,dir,modern);check(same(trimmed,reference)&&trimmed.tuneSourceOffset==7200,"Trimmed processed regions map back to the correct dry samples");
  Core.Clip right=a.copy();right.offset=12000;right.length-=12000;right.envelopeOffset=12000;Core.Clip rightRef=dryRegion.copy();rightRef.offset+=12000;rightRef.length=right.length;rightRef.envelopeOffset=12000;AudioIO.correctClip(right,dir,modern);AudioIO.correctClip(rightRef,dir,modern);check(same(right,rightRef),"Copied/split right-hand regions retain their dry mapping");
  Core.Clip restored=a.copy();AudioIO.restoreUntunedClip(restored,dir);check(same(restored,dryRegion)&&restored.tuneSourceFile==null&&restored.offset==2400,"Restore dry is sample-identical and clears processing provenance");
  Core.Session session=new Core.Session();session.directory=dir.getPath();Core.Track track=new Core.Track("Vocal",0);track.clips.add(a);session.tracks.add(track);AudioIO.save(session);Core.Session loaded=AudioIO.load(dir);check(loaded.tracks.get(0).clips.get(0).tuneSourceFile.equals(original.file),"Dry source association persists in saved projects");AudioIO.correctClip(loaded.tracks.get(0).clips.get(0),dir,modern);check(same(loaded.tracks.get(0).clips.get(0),fresh),"Re-tuning after project reload still starts from dry");
  ByteArrayOutputStream portable=new ByteArrayOutputStream();AudioIO.backup(portable,session);File backupDir=new File(dir,"restored");backupDir.mkdir();Core.Session backup=AudioIO.restore(new ByteArrayInputStream(portable.toByteArray()),backupDir);check(new File(backupDir,original.file).isFile(),"Portable backup includes the preserved original even when no region plays it");Core.Clip backed=backup.tracks.get(0).clips.get(0);AudioIO.correctClip(backed,backupDir,modern);check(same(backed,fresh),"Restored backup can re-tune from its included original");
  for(boolean preserve:new boolean[]{false,true}){Core.Session changed=AudioIO.retimeProject(session,125,preserve);Core.Clip c=changed.tracks.get(0).clips.get(0);Core.Clip source=c.copy();AudioIO.restoreUntunedClip(source,dir);check(source.offset>=0&&source.offset+(long)source.length<=source.source.frames(),"Tempo edits retime dry source mapping safely: "+preserve);Core.Clip test=c.copy();AudioIO.correctClip(test,dir,modern);AudioIO.correctClip(source,dir,modern);check(same(test,source),"Post-tempo re-tuning matches a fresh pass from retimed dry: "+preserve);}
  org.json.JSONObject bad=new org.json.JSONObject(new String(Files.readAllBytes(new File(dir,"session.json").toPath()),"UTF-8"));bad.getJSONArray("tracks").getJSONObject(0).getJSONArray("clips").getJSONObject(0).put("tuneSourceFile","../outside.pcm");Files.write(new File(dir,"session.json").toPath(),bad.toString().getBytes("UTF-8"));boolean refused=false;try{AudioIO.load(dir);}catch(IOException e){refused=true;}check(refused,"Original-source path traversal is rejected");remove(dir);System.out.println(passed+" dry-source and non-stacking tuning checks passed.");
 }
}
